    unit->movement.fine_pose=unit->movement.sampled_pose=(vec2_t){wc3_float(0x3fb7b01a),wc3_float(0x3fe4fca7)};
    unit->movement.pose_world=unit->s.origin2; unit->movement.pose_valid=true;
